package br.com.ajudamutua.service;
import br.com.ajudamutua.model.*; import br.com.ajudamutua.repository.LedgerEntryRepository; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.Instant; import java.util.HexFormat; import java.util.UUID;
@Service public class LedgerService {private static final String GENESIS="0".repeat(64);private final LedgerEntryRepository repo;private final JdbcTemplate jdbc;public LedgerService(LedgerEntryRepository repo,JdbcTemplate jdbc){this.repo=repo;this.jdbc=jdbc;}
 @Transactional public LedgerEntry append(LedgerType type,BigDecimal signedAmount,UUID memberId,UUID aidRequestId,String description){jdbc.queryForObject("select id from ledger_chain_lock where id=1 for update",Integer.class);String prev=repo.findTopByOrderByCreatedAtDesc().map(LedgerEntry::getEntryHash).orElse(GENESIS);UUID id=UUID.randomUUID();Instant now=Instant.now();String payload=id+"|"+type+"|"+signedAmount.toPlainString()+"|"+memberId+"|"+aidRequestId+"|"+description+"|"+now+"|"+prev;String hash=sha256(payload);return repo.save(new LedgerEntry(id,type,signedAmount,memberId,aidRequestId,description,now,prev,hash));}
 public BigDecimal balance(){return repo.balance();} private String sha256(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
